from __future__ import annotations

import base64
import gzip
import hashlib

ENCODED_PATCH = ""
EXPECTED_PATCH_SHA256 = "e8c0df993005022fc1bdf28a61ecd06538cffd064b0a52e88ad083439d2c256b"

compressed = base64.b64decode(ENCODED_PATCH, validate=True)
patch = gzip.decompress(compressed)
actual = hashlib.sha256(patch).hexdigest()
if actual != EXPECTED_PATCH_SHA256:
    raise SystemExit(f"readiness patch SHA-256 mismatch: {actual}")
exec(compile(patch, "<full-language-readiness-patch>", "exec"), {"__name__": "__main__"})
